687	+// retryDelay honours a Retry-After header given in seconds, else returns def.
688	+func retryDelay(resp *http.Response, def time.Duration) time.Duration {
689	+	if resp == nil {
690	+		return def
691	+	}
692	+	if secs, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil && secs > 0 && secs <= 30 {
693	+		return time.Duration(secs) * time.Second
694	+	}
695	+	return def
696	+}
