698	+// readPayout decodes an accepted payout or returns a rejectedError.
699	+func readPayout(resp *http.Response) (PayoutResult, error) {
700	+	defer resp.Body.Close()
701	+	if resp.StatusCode >= 400 {
702	+		msg, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
703	+		return PayoutResult{}, &rejectedError{status: resp.StatusCode, body: string(msg)}
704	+	}
705	+	var out PayoutResult
706	+	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
707	+		return PayoutResult{}, fmt.Errorf("decode payout response: %w", err)
708	+	}
709	+	return out, nil
710	+}
