12		// ErrNotFound is returned when a looked-up row does not exist.
13		ErrNotFound = errors.New("not found")
14		// ErrInsufficientFunds is returned when a debit would overdraw an account.
15		ErrInsufficientFunds = errors.New("insufficient funds")
16	)
17	
18	// lookupError says which row a failed lookup was for.
19	type lookupError struct {
20		what string
21		id   int64
22		err  error
23	}
24	
25	func (e *lookupError) Error() string {
26		return fmt.Sprintf("get %s %d: %v", e.what, e.id, e.err)
27	}
28	
29	// Account is a single-currency wallet. Balances are kept in minor units
30	// (cents) to avoid floating point.
31	type Account struct {
32		ID           int64
33		OwnerID      int64
34		Currency     string
35		BalanceCents int64
36		CreatedAt    time.Time
37	}
38	
39	// Entry is one line of an account's ledger. AmountCents is positive for
40	// credits and negative for debits.
41	type Entry struct {
42		ID          int64
43		AccountID   int64
44		AmountCents int64
45		Kind        string
46		Reference   string
47		CreatedAt   time.Time
48	}
49	
50	// Transfer moves money between two accounts of the same currency.
51	type Transfer struct {
52		ID            int64     `json:"id"`
53		FromAccountID int64     `json:"from_account_id"`
54		ToAccountID   int64     `json:"to_account_id"`
55		AmountCents   int64     `json:"amount_cents"`
56		Memo          string    `json:"memo,omitempty"`
57		CreatedAt     time.Time `json:"created_at"`
58	}
59	
60	// Store is the persistence layer. All amounts are in minor units.
61	type Store struct {
62		db *sql.DB
63	}
64	
65	func NewStore(db *sql.DB) *Store { return &Store{db: db} }
66	
67	// UserForToken returns the user owning the (hashed) API token.
68	func (s *Store) UserForToken(ctx context.Context, tokenHash string) (int64, error) {
69		var userID int64
70		err := s.db.QueryRowContext(ctx,
71			`SELECT user_id FROM api_tokens WHERE token_hash = ? AND revoked_at IS NULL`,
72			tokenHash).Scan(&userID)
73		if errors.Is(err, sql.ErrNoRows) {
74			return 0, ErrNotFound
75		}
76		if err != nil {
77			return 0, fmt.Errorf("look up token: %w", err)
78		}
79		return userID, nil
80	}
81	
82	func (s *Store) GetAccount(ctx context.Context, id int64) (Account, error) {
83		var a Account
84		err := s.db.QueryRowContext(ctx,
85			`SELECT id, owner_id, currency, balance_cents, created_at FROM accounts WHERE id = ?`, id).
86			Scan(&a.ID, &a.OwnerID, &a.Currency, &a.BalanceCents, &a.CreatedAt)
87		if errors.Is(err, sql.ErrNoRows) {
88			return Account{}, &lookupError{what: "account", id: id, err: ErrNotFound}
89		}
90		if err != nil {
91			return Account{}, &lookupError{what: "account", id: id, err: err}
92		}
93		return a, nil
94	}
95	
96	// ListEntries returns up to limit entries of an account with an id below
97	// before, newest first. Pass before = 0 to start from the newest entry.
98	func (s *Store) ListEntries(ctx context.Context, accountID, before int64, limit int) ([]Entry, error) {
99		if before <= 0 {
100			before = 1<<63 - 1
101		}
102		rows, err := s.db.QueryContext(ctx,
103			`SELECT id, account_id, amount_cents, kind, reference, created_at
104			   FROM entries
105			  WHERE account_id = ? AND id < ?
106			  ORDER BY id DESC
107			  LIMIT ?`, accountID, before, limit)
108		if err != nil {
109			return nil, fmt.Errorf("list entries: %w", err)
110		}
111		return scanEntries(rows)
112	}
113	
114	// scanEntries reads all rows into entries and closes rows.
115	func scanEntries(rows *sql.Rows) ([]Entry, error) {
116		defer rows.Close()
117		var out []Entry
118		for rows.Next() {
119			var e Entry
120			if err := rows.Scan(&e.ID, &e.AccountID, &e.AmountCents, &e.Kind, &e.Reference, &e.CreatedAt); err != nil {
121				return nil, fmt.Errorf("scan entry: %w", err)
122			}
123			out = append(out, e)
124		}
125		return out, rows.Err()
126	}
127	
128	// SentSince sums the transfers an account has sent since the given time.
129	func (s *Store) SentSince(ctx context.Context, accountID int64, since time.Time) (int64, error) {
130		var sent int64
131		err := s.db.QueryRowContext(ctx,
132			`SELECT COALESCE(SUM(-amount_cents), 0)
133			   FROM entries
134			  WHERE account_id = ? AND kind = ? AND created_at >= ?`,
135			accountID, "transfer_out", since.UTC()).Scan(&sent)
136		if err != nil {
137			return 0, fmt.Errorf("sum transfers of account %d: %w", accountID, err)
138		}
139		return sent, nil
140	}
141	
142	// Credit adds money to an account and records the matching ledger entry of
143	// the given kind in one transaction.
144	func (s *Store) Credit(ctx context.Context, accountID, amountCents int64, kind, reference string) (Entry, error) {
145		tx, err := s.db.BeginTx(ctx, nil)
146		if err != nil {
147			return Entry{}, err
148		}
149		defer tx.Rollback()
150	
151		if err := adjustBalance(ctx, tx, accountID, amountCents); err != nil {
152			return Entry{}, err
153		}
154		e, err := insertEntry(ctx, tx, Entry{
155			AccountID:   accountID,
156			AmountCents: amountCents,
157			Kind:        kind,
158			Reference:   reference,
159		})
160		if err != nil {
161			return Entry{}, err
162		}
163		return e, tx.Commit()
164	}
165	
166	// Withdraw debits an account for a payout.
167	func (s *Store) Withdraw(ctx context.Context, accountID, amountCents int64, reference string) (Entry, error) {
168		tx, err := s.db.BeginTx(ctx, nil)
169		if err != nil {
170			return Entry{}, err
171		}
172		defer tx.Rollback()
173	
174		if err := adjustBalance(ctx, tx, accountID, -amountCents); err != nil {
175			return Entry{}, fmt.Errorf("debit account %d: %w", accountID, err)
176		}
177		e, err := insertEntry(ctx, tx, Entry{
178			AccountID:   accountID,
179			AmountCents: -amountCents,
180			Kind:        "payout",
181			Reference:   reference,
182		})
183		if err != nil {
184			return Entry{}, err
185		}
186		return e, tx.Commit()
187	}
188	
189	// CreateTransfer records a transfer, moves the money and writes one ledger
190	// entry on each side, all in one transaction.
191	func (s *Store) CreateTransfer(ctx context.Context, t Transfer) (Transfer, error) {
192		tx, err := s.db.BeginTx(ctx, nil)
193		if err != nil {
194			return Transfer{}, fmt.Errorf("begin transfer: %w", err)
195		}
196		defer func() {
197			if err != nil {
198				_ = tx.Rollback()
199				return
200			}
201			err = tx.Commit()
202		}()
203	
204		t.CreatedAt = time.Now().UTC()
205		res, err := tx.ExecContext(ctx,
206			`INSERT INTO transfers (from_account_id, to_account_id, amount_cents, memo, created_at)
207			 VALUES (?, ?, ?, ?, ?)`,
208			t.FromAccountID, t.ToAccountID, t.AmountCents, t.Memo, t.CreatedAt)
209		if err != nil {
210			return Transfer{}, fmt.Errorf("insert transfer: %w", err)
211		}
212		if t.ID, err = res.LastInsertId(); err != nil {
213			return Transfer{}, err
214		}
215	
216		if err := adjustBalance(ctx, tx, t.FromAccountID, -t.AmountCents); err != nil {
217			return Transfer{}, fmt.Errorf("debit account %d: %w", t.FromAccountID, err)
218		}
219		if err := adjustBalance(ctx, tx, t.ToAccountID, t.AmountCents); err != nil {
220			return Transfer{}, fmt.Errorf("credit account %d: %w", t.ToAccountID, err)
221		}
222	
223		ref := transferReference(t.ID)
224		for _, e := range []Entry{
225			{AccountID: t.FromAccountID, AmountCents: -t.AmountCents, Kind: "transfer_out", Reference: ref},
226			{AccountID: t.ToAccountID, AmountCents: t.AmountCents, Kind: "transfer_in", Reference: ref},
227		} {
228			if _, err := insertEntry(ctx, tx, e); err != nil {
229				return Transfer{}, err
230			}
231		}
232		return t, nil
233	}
234	
235	func (s *Store) GetTransfer(ctx context.Context, id int64) (Transfer, error) {
236		var t Transfer
237		err := s.db.QueryRowContext(ctx,
238			`SELECT id, from_account_id, to_account_id, amount_cents, memo, created_at FROM transfers WHERE id = ?`, id).
239			Scan(&t.ID, &t.FromAccountID, &t.ToAccountID, &t.AmountCents, &t.Memo, &t.CreatedAt)
240		if errors.Is(err, sql.ErrNoRows) {
241			return Transfer{}, &lookupError{what: "transfer", id: id, err: ErrNotFound}
242		}
243		if err != nil {
244			return Transfer{}, &lookupError{what: "transfer", id: id, err: err}
245		}
246		return t, nil
247	}
248	
249	// adjustBalance adds delta (which may be negative) to an account's balance.
250	func adjustBalance(ctx context.Context, tx *sql.Tx, accountID, delta int64) error {
251		res, err := tx.ExecContext(ctx,
252			`UPDATE accounts SET balance_cents = balance_cents + ? WHERE id = ?`, delta, accountID)
253		if err != nil {
254			return err
255		}
256		n, err := res.RowsAffected()
257		if err != nil {
258			return err
259		}
260		if n == 0 {
261			return ErrNotFound
262		}
263		return nil
264	}
265	
266	func insertEntry(ctx context.Context, tx *sql.Tx, e Entry) (Entry, error) {
267		e.CreatedAt = time.Now().UTC()
268		res, err := tx.ExecContext(ctx,
269			`INSERT INTO entries (account_id, amount_cents, kind, reference, created_at) VALUES (?, ?, ?, ?, ?)`,
270			e.AccountID, e.AmountCents, e.Kind, e.Reference, e.CreatedAt)
271		if err != nil {
272			return Entry{}, fmt.Errorf("insert entry: %w", err)
273		}
274		if e.ID, err = res.LastInsertId(); err != nil {
275			return Entry{}, err
276		}
277		return e, nil
278	}
279	
280	func transferReference(id int64) string {
281		return fmt.Sprintf("tr_%d", id)
282	}
