1	package main
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"log"
10		"net/http"
11		"strconv"
12		"time"
13	)
14	
15	// PayoutClient sends money from a wallet to an external bank account through
16	// the payout provider's HTTP API.
17	type PayoutClient struct {
18		baseURL     string
19		apiKey      string
20		http        *http.Client
21		maxAttempts int
22		backoff     time.Duration
23	}
24	
25	// PayoutRequest is what the wallet asks the provider to pay out.
26	type PayoutRequest struct {
27		AmountCents int64
28		Currency    string
29		Destination string // provider token for the bank account
30		Reference   string // also sent as the idempotency key
31	}
32	
33	// PayoutResult is the provider's answer to an accepted payout.
34	type PayoutResult struct {
35		ProviderID string `json:"id"`
36		Status     string `json:"status"`
37	}
38	
39	// providerPayout is the provider's wire format.
40	type providerPayout struct {
41		AmountMinor int32  `json:"amount_minor"`
42		Currency    string `json:"currency"`
43		Destination string `json:"destination"`
44		Reference   string `json:"reference"`
45	}
46	
47	// rejectedError is a 4xx answer from the provider. Retrying cannot help.
48	type rejectedError struct {
49		status int
50		body   string
51	}
52	
53	func (e *rejectedError) Error() string {
54		return fmt.Sprintf("payout rejected: status %d: %s", e.status, e.body)
55	}
56	
57	// Send asks the provider to pay out p. Network errors, 429 and 5xx answers
58	// are retried with exponential backoff (or the provider's Retry-After); the
59	// provider deduplicates retries by the idempotency key.
60	func (c *PayoutClient) Send(ctx context.Context, p PayoutRequest) (PayoutResult, error) {
61		body, err := json.Marshal(providerPayout{
62			AmountMinor: int32(p.AmountCents),
63			Currency:    p.Currency,
64			Destination: p.Destination,
65			Reference:   p.Reference,
66		})
67		if err != nil {
68			return PayoutResult{}, err
69		}
70	
71		for attempt := 1; attempt <= c.maxAttempts; attempt++ {
72			resp, err := c.post(ctx, body, p.Reference)
73			if err == nil && !retryableStatus(resp.StatusCode) {
74				return readPayout(resp)
75			}
76			if err == nil {
77				err = fmt.Errorf("payout provider: status %d", resp.StatusCode)
78			}
79			log.Printf("payout %s: attempt %d/%d: %v", p.Reference, attempt, c.maxAttempts, err)
80	
81			if attempt < c.maxAttempts {
82				select {
83				case <-time.After(retryDelay(resp, c.backoff<<(attempt-1))):
84				case <-ctx.Done():
85					return PayoutResult{}, ctx.Err()
86				}
87			}
88			if resp != nil {
89				resp.Body.Close()
90			}
91		}
92		return PayoutResult{}, err
93	}
94	
95	func (c *PayoutClient) post(ctx context.Context, body []byte, idempotencyKey string) (*http.Response, error) {
96		req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/v1/payouts", bytes.NewReader(body))
97		if err != nil {
98			return nil, err
99		}
100		req.Header.Set("Content-Type", "application/json")
101		req.Header.Set("Authorization", "Bearer "+c.apiKey)
102		req.Header.Set("Idempotency-Key", idempotencyKey)
103		return c.http.Do(req)
104	}
105	
106	func retryableStatus(code int) bool {
107		return code == http.StatusTooManyRequests || code >= 500
108	}
109	
110	// retryDelay honours a Retry-After header given in seconds, else returns def.
111	func retryDelay(resp *http.Response, def time.Duration) time.Duration {
112		if resp == nil {
113			return def
114		}
115		if secs, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil && secs > 0 && secs <= 30 {
116			return time.Duration(secs) * time.Second
117		}
118		return def
119	}
120	
121	// readPayout decodes an accepted payout or returns a rejectedError.
122	func readPayout(resp *http.Response) (PayoutResult, error) {
123		defer resp.Body.Close()
124		if resp.StatusCode >= 400 {
125			msg, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
126			return PayoutResult{}, &rejectedError{status: resp.StatusCode, body: string(msg)}
127		}
128		var out PayoutResult
129		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
130			return PayoutResult{}, fmt.Errorf("decode payout response: %w", err)
131		}
132		return out, nil
133	}
