3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"time"
11	)
12	
13	// Event is posted to the configured webhook when money moves.
14	type Event struct {
15		Type        string    `json:"type"`
16		AccountID   int64     `json:"account_id"`
17		AmountCents int64     `json:"amount_cents"`
18		Currency    string    `json:"currency"`
19		Summary     string    `json:"summary"`
20		Reference   string    `json:"reference,omitempty"`
21		At          time.Time `json:"at"`
22	}
23	
24	// Notifier delivers events to a webhook endpoint.
25	type Notifier struct {
26		url    string
27		client *http.Client
28	}
29	
30	func NewNotifier(url string, timeout time.Duration) *Notifier {
31		return &Notifier{url: url, client: &http.Client{Timeout: timeout}}
32	}
33	
34	// NotifyWithin delivers ev but stops waiting for the webhook after wait, so a
35	// slow endpoint cannot hold up an API response.
36	func (n *Notifier) NotifyWithin(ev Event, wait time.Duration) error {
37		if n.url == "" {
38			return nil
39		}
40		// Not tied to the request context: the request may finish first.
41		done := goResult(func() error { return n.Notify(context.Background(), ev) })
42		return waitOrTimeout(done, wait)
43	}
44	
45	// Notify posts ev to the webhook. It is a no-op when no URL is configured.
46	func (n *Notifier) Notify(ctx context.Context, ev Event) error {
47		if n.url == "" {
48			return nil
49		}
50		ev.Summary = fmt.Sprintf("%s of %.2f %s on account %d", ev.Type, float64(ev.AmountCents)/100, ev.Currency, ev.AccountID)
51		body, err := json.Marshal(ev)
52		if err != nil {
53			return err
54		}
55		req, err := http.NewRequestWithContext(ctx, http.MethodPost, n.url, bytes.NewReader(body))
56		if err != nil {
57			return err
58		}
59		req.Header.Set("Content-Type", "application/json")
60	
61		resp, err := n.client.Do(req)
62		if err != nil {
63			return err
64		}
65		defer resp.Body.Close()
66		_, _ = io.Copy(io.Discard, resp.Body)
67	
68		if resp.StatusCode >= 300 {
69			return fmt.Errorf("webhook: unexpected status %d", resp.StatusCode)
70		}
71		return nil
72	}
