1	package main
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"log"
8		"net/http"
9		"strconv"
10		"time"
11	)
12	
13	// maxPayoutCents is the largest single payout the API accepts.
14	const maxPayoutCents = 25_000_000
15	
16	// ServerOptions are the tunables of the HTTP layer.
17	type ServerOptions struct {
18		MaxPageSize int
19		NotifyWait  time.Duration
20		DailyLimit  int64
21		Location    *time.Location
22	}
23	
24	// Server holds the dependencies of the HTTP handlers.
25	type Server struct {
26		store    *Store
27		notifier *Notifier
28		payouts  *PayoutClient
29		opts     ServerOptions
30	}
31	
32	type accountJSON struct {
33		ID           int64     `json:"id"`
34		Currency     string    `json:"currency"`
35		BalanceCents int64     `json:"balance_cents"`
36		CreatedAt    time.Time `json:"created_at"`
37	}
38	
39	type entryJSON struct {
40		ID          int64     `json:"id"`
41		AmountCents int64     `json:"amount_cents"`
42		Amount      string    `json:"amount"`
43		Kind        string    `json:"kind"`
44		Reference   string    `json:"reference,omitempty"`
45		CreatedAt   time.Time `json:"created_at"`
46	}
47	
48	func toEntryJSON(e Entry, currency string) entryJSON {
49		return entryJSON{
50			ID:          e.ID,
51			AmountCents: e.AmountCents,
52			Amount:      FormatAmount(e.AmountCents, currency),
53			Kind:        e.Kind,
54			Reference:   e.Reference,
55			CreatedAt:   e.CreatedAt,
56		}
57	}
58	
59	func (s *Server) getAccount(w http.ResponseWriter, r *http.Request) {
60		acct := accountFrom(r.Context())
61		writeJSON(w, http.StatusOK, accountJSON{
62			ID:           acct.ID,
63			Currency:     acct.Currency,
64			BalanceCents: acct.BalanceCents,
65			CreatedAt:    acct.CreatedAt,
66		})
67	}
68	
69	func (s *Server) listEntries(w http.ResponseWriter, r *http.Request) {
70		acct := accountFrom(r.Context())
71		q := r.URL.Query()
72	
73		limit := s.opts.MaxPageSize
74		if v := q.Get("limit"); v != "" {
75			n, err := strconv.Atoi(v)
76			if err != nil || n <= 0 {
77				writeErr(w, http.StatusBadRequest, "limit must be a positive integer")
78				return
79			}
80			limit = min(n, s.opts.MaxPageSize)
81		}
82		var before int64
83		if v := q.Get("before"); v != "" {
84			n, err := strconv.ParseInt(v, 10, 64)
85			if err != nil || n <= 0 {
86				writeErr(w, http.StatusBadRequest, "before must be a positive entry id")
87				return
88			}
89			before = n
90		}
91	
92		entries, err := s.store.ListEntries(r.Context(), acct.ID, before, limit)
93		if err != nil {
94			writeStoreError(w, "list entries", err)
95			return
96		}
97		out := make([]entryJSON, 0, len(entries))
98		for _, e := range entries {
99			out = append(out, toEntryJSON(e, acct.Currency))
100		}
101		writeJSON(w, http.StatusOK, map[string]any{"entries": out})
102	}
103	
104	type depositRequest struct {
105		AmountCents int64  `json:"amount_cents"`
106		Reference   string `json:"reference"`
107	}
108	
109	func (s *Server) createDeposit(w http.ResponseWriter, r *http.Request) {
110		acct := accountFrom(r.Context())
111		var req depositRequest
112		if err := decodeJSON(r, &req); err != nil {
113			writeErr(w, http.StatusBadRequest, err.Error())
114			return
115		}
116		if req.AmountCents <= 0 {
117			writeErr(w, http.StatusBadRequest, "amount_cents must be positive")
118			return
119		}
120	
121		e, err := s.store.Credit(r.Context(), acct.ID, req.AmountCents, "deposit", req.Reference)
122		if err != nil {
123			writeStoreError(w, "deposit", err)
124			return
125		}
126		s.notify(Event{Type: "deposit", AccountID: acct.ID, AmountCents: e.AmountCents, Currency: acct.Currency, Reference: e.Reference, At: e.CreatedAt})
127		writeJSON(w, http.StatusCreated, toEntryJSON(e, acct.Currency))
128	}
129	
130	type payoutRequest struct {
131		AmountCents int64  `json:"amount_cents"`
132		Destination string `json:"destination"`
133	}
134	
135	func (s *Server) createPayout(w http.ResponseWriter, r *http.Request) {
136		acct := accountFrom(r.Context())
137		var req payoutRequest
138		if err := decodeJSON(r, &req); err != nil {
139			writeErr(w, http.StatusBadRequest, err.Error())
140			return
141		}
142		if req.AmountCents <= 0 || req.AmountCents > maxPayoutCents {
143			writeErr(w, http.StatusBadRequest, fmt.Sprintf("amount_cents must be between 1 and %d", maxPayoutCents))
144			return
145		}
146		if req.Destination == "" {
147			writeErr(w, http.StatusBadRequest, "destination is required")
148			return
149		}
150		if acct.BalanceCents < req.AmountCents {
151			writeStoreError(w, "payout", ErrInsufficientFunds)
152			return
153		}
154	
155		ref, err := newReference("po")
156		if err != nil {
157			writeStoreError(w, "payout reference", err)
158			return
159		}
160		e, err := s.store.Withdraw(r.Context(), acct.ID, req.AmountCents, ref)
161		if err != nil {
162			writeStoreError(w, "payout debit", err)
163			return
164		}
165	
166		res, err := s.payouts.Send(r.Context(), PayoutRequest{
167			AmountCents: req.AmountCents,
168			Currency:    acct.Currency,
169			Destination: req.Destination,
170			Reference:   ref,
171		})
172		if err != nil {
173			log.Printf("payout %s for account %d failed: %v", ref, acct.ID, err)
174			if _, rerr := s.store.Credit(r.Context(), acct.ID, req.AmountCents, "payout_reversal", ref); rerr != nil {
175				log.Printf("payout %s: reversal failed, manual fix needed: %v", ref, rerr)
176			}
177			writeErr(w, http.StatusBadGateway, "payout provider did not accept the payout")
178			return
179		}
180	
181		s.notify(Event{Type: "payout", AccountID: acct.ID, AmountCents: e.AmountCents, Currency: acct.Currency, Reference: ref, At: e.CreatedAt})
182		writeJSON(w, http.StatusAccepted, map[string]any{
183			"entry":       toEntryJSON(e, acct.Currency),
184			"provider_id": res.ProviderID,
185			"status":      res.Status,
186		})
187	}
