196	var errTimeout = errors.New("timed out")
197	
198	// waitOrTimeout returns the result from done, or errTimeout if it takes
199	// longer than d.
200	func waitOrTimeout(done <-chan error, d time.Duration) error {
201		t := time.NewTimer(d)
202		defer t.Stop()
203		select {
204		case err := <-done:
205			return err
206		case <-t.C:
207			return errTimeout
208		}
209	}
