211	// pathID parses the {id} path segment.
212	func pathID(r *http.Request) (int64, error) {
213		id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
214		if err != nil || id <= 0 {
215			return 0, errors.New("invalid id in path")
216		}
217		return id, nil
218	}
219	
220	// decodeJSON reads a small JSON body into dst and rejects unknown fields.
221	func decodeJSON(r *http.Request, dst any) error {
222		dec := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<16))
223		dec.DisallowUnknownFields()
224		if err := dec.Decode(dst); err != nil {
225			return fmt.Errorf("invalid request body: %w", err)
226		}
227		return nil
228	}
229	
230	func writeJSON(w http.ResponseWriter, status int, v any) {
231		w.Header().Set("Content-Type", "application/json")
232		w.WriteHeader(status)
233		if err := json.NewEncoder(w).Encode(v); err != nil {
234			log.Printf("write response: %v", err)
235		}
236	}
237	
238	// writeCreated answers 201 with v and the location of the new resource.
239	func writeCreated(w http.ResponseWriter, location string, v any) {
240		w.Header().Set("Location", location)
241		writeJSON(w, http.StatusCreated, v)
242	}
243	
244	func writeErr(w http.ResponseWriter, status int, msg string) {
245		writeJSON(w, status, map[string]string{"error": msg})
246	}
247	
248	// writeStoreError maps an error from the store (or a check built on it) to
249	// an HTTP response. Unexpected errors are logged with op and reported as 500.
250	func writeStoreError(w http.ResponseWriter, op string, err error) {
251		switch {
252		case errors.Is(err, ErrNotFound):
253			writeErr(w, http.StatusNotFound, "not found")
254		case errors.Is(err, ErrInsufficientFunds):
255			writeErr(w, http.StatusConflict, "insufficient funds")
256		case errors.Is(err, ErrDailyLimit):
257			writeErr(w, http.StatusUnprocessableEntity, "daily transfer limit reached")
258		default:
259			log.Printf("%s: %v", op, err)
260			writeErr(w, http.StatusInternalServerError, "internal error")
261		}
262	}
