73	func (s *Server) getTransfer(w http.ResponseWriter, r *http.Request) {
74		id, err := pathID(r)
75		if err != nil {
76			writeErr(w, http.StatusBadRequest, err.Error())
77			return
78		}
79		t, err := s.store.GetTransfer(r.Context(), id)
80		if err != nil {
81			writeStoreError(w, "get transfer", err)
82			return
83		}
84		writeJSON(w, http.StatusOK, t)
85	}
