87	// checkDailyLimit returns ErrDailyLimit if sending amount now would take the
88	// account over its limit for the current business day.
89	func (s *Server) checkDailyLimit(ctx context.Context, accountID, amount int64) error {
90		if s.opts.DailyLimit <= 0 {
91			return nil
92		}
93		since := startOfBusinessDay(time.Now(), s.opts.Location)
94		sent, err := s.store.SentSince(ctx, accountID, since)
95		if err != nil {
96			return err
97		}
98		if sent+amount > s.opts.DailyLimit {
99			return ErrDailyLimit
100		}
101		return nil
102	}
