104	// newReference returns a random reference such as "po_3f9a0c2b1d4e5f60".
105	func newReference(prefix string) (string, error) {
106		var b [8]byte
107		if _, err := rand.Read(b[:]); err != nil {
108			return "", err
109		}
110		return prefix + "_" + hex.EncodeToString(b[:]), nil
111	}
112	
113	// goResult runs f on its own goroutine and delivers its result on the
114	// returned channel.
115	func goResult(f func() error) <-chan error {
116		ch := make(chan error)
117		go func() { ch <- f() }()
118		return ch
119	}
